import { useMemo } from 'react';
import { Link } from 'react-router-dom';
import { toHex } from '@cipherbox/client';
import { AppShell } from '../components/layout/AppShell';
import { useReceivedShares } from '../hooks/useReceivedShares';
import { folderPath } from '../lib/nodeId';
import { shareStanding, type ReceivedShareStanding } from '../sharing/receivedShares';
import { displayName } from '../vault/displayName';

interface Row {
  scope: string;
  /** The vault-browser route for the scope root: a share opens in the one browser. */
  path: string;
  sharer: string;
  displayName: string;
  permission: string;
  /** The engine's own class name, or `none` where no pass has answered. */
  resolution: string;
  standing: ReceivedShareStanding;
}

/**
 * The shares this vault accepted, behind `RequireAuth` (blueprint/web-client.md
 * "Composition"). Each row carries the engine's own resolution verdict, so a
 * removal the owner published is discovered here rather than delivered.
 */
export function SharedPage() {
  const { shares, busy, error, reload } = useReceivedShares();

  const rows: Row[] | null = useMemo(
    () =>
      shares?.map((share) => ({
        scope: toHex(share.scope),
        path: folderPath(share.scope),
        sharer: toHex(share.sharerIdentityPublicKey),
        displayName: displayName(share.displayName),
        permission: share.permission,
        resolution: share.resolution ?? 'none',
        standing: shareStanding(share.resolution),
      })) ?? null,
    [shares]
  );

  return (
    <AppShell>
      <div className="route-page" data-testid="shared-page">
        <h2 className="route-heading">shared with you</h2>
        <p className="sharing-note">
          {'// every folder another vault granted you, and where each one stands now'}
        </p>

        {error !== null && (
          <p className="dialog-error" role="alert" data-testid="shared-error">
            {error}
          </p>
        )}

        {rows === null ? (
          error === null && (
            <p className="sharing-note" data-testid="shared-unread">
              {'// the accepted list has not been read yet'}
            </p>
          )
        ) : rows.length === 0 ? (
          <p className="sharing-note" data-testid="shared-empty">
            {'// nothing has been shared with you yet'}
          </p>
        ) : (
          <ul className="sharing-list" data-testid="shared-list">
            {rows.map((row) => (
              <li
                key={`${row.sharer}:${row.scope}`}
                className="sharing-row sharing-row--shared"
                data-testid="shared-row"
                data-scope={row.scope}
              >
                <span className="shared-name" data-testid="shared-name">
                  {row.displayName}
                </span>
                <span className="sharing-key" data-testid="shared-sharer">
                  {row.sharer}
                </span>
                <span className="details-badge" data-testid="shared-permission">
                  {row.permission}
                </span>
                <Link
                  className="terminal-btn shared-open"
                  to={row.path}
                  data-testid="shared-open"
                  aria-label={`open ${row.displayName}`}
                >
                  open
                </Link>
                <span
                  className="shared-standing"
                  data-testid="shared-standing"
                  data-resolution={row.resolution}
                  data-tone={row.standing.tone}
                >
                  {row.standing.label}
                </span>
              </li>
            ))}
          </ul>
        )}

        <button
          type="button"
          className="terminal-btn"
          onClick={() => void reload()}
=== page object
   */
  async open(): Promise<void> {
    await this.page.getByTestId('nav-item-shared').click();
    await expect(this.panel).toBeVisible();
  }

  /**
   * Re-reads the accepted list. The verdicts move on the engine's focus tick,
   * so a spec that changed a grant refreshes first and then re-reads here.
   */
  async readAgain(): Promise<void> {
    await this.page.getByTestId('shared-reload').click();
  }

  get rows(): Locator {
    return this.page.getByTestId('shared-row');
  }

  /**
   * Re-reads until the one accepted share reports `resolution`. The verdict
   * moves on the engine's sync pass, so each turn nudges that pass as well as
   * the list.
   */
  async awaitStanding(resolution: string, timeout = 60_000): Promise<void> {
    await expect
      .poll(
        async () => {
          await this.page.getByTestId('status-indicator').click();
          await this.readAgain();
          if ((await this.rows.count()) !== 1) return 'no row';
          return this.rows.getByTestId('shared-standing').getAttribute('data-resolution');
        },
        { timeout, intervals: [5_000] }
      )
      .toBe(resolution);
  }

  /**
   * Re-reads the list, and nothing else, until the row for `scope` reports
   * `resolution`. A manual refresh answers at its read legs, ahead of the
   * share legs of the same pass, so the verdict that pass records can land
   * after the refresh returns.
   */
  async readStanding(scope: string, resolution: string, timeout = 10_000): Promise<void> {
    await expect
      .poll(
        async () => {
          await this.readAgain();
          const standing = this.row(scope).getByTestId('shared-standing');
          if ((await standing.count()) !== 1) return 'no row';
          return standing.getAttribute('data-resolution');

